describeMatrix("serve static range requests", (t, { it, expect }) => {
  const body = "0123456789".repeat(100);
  let getContents: Mock<() => string>;

  beforeEach(() => {
    getContents = vi.fn(() => body);
    t.app.all("/range/**", (event) =>
      serveStatic(event, {
        getContents,
        getMeta: () => ({ type: "text/plain", etag: '"abc"', size: 1000 }),
      }),
    );
  });

  it("advertises accept-ranges on a full response", async () => {
    const res = await t.fetch("/range/a.txt");
    expect(res.status).toBe(200);
    expect(res.headers.get("accept-ranges")).toBe("bytes");
    expect(res.headers.get("content-range")).toBeNull();
    expect(await res.text()).toBe(body);
  });

  it("serves the requested bytes with 206", async () => {
    const res = await t.fetch("/range/a.txt", { headers: { range: "bytes=0-99" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-99/1000");
    expect(res.headers.get("content-length")).toBe("100");
    expect(await res.text()).toBe(body.slice(0, 100));
  });

  it("supports suffix and open-ended ranges", async () => {
    for (const [range, start, end] of [
      ["bytes=-100", 900, 999],
      ["bytes=990-", 990, 999],
      ["bytes=990-5000", 990, 999],
      ["bytes=-5000", 0, 999],
    ] as const) {
      const res = await t.fetch("/range/a.txt", { headers: { range } });
      expect(res.status, range).toBe(206);
      expect(res.headers.get("content-range"), range).toBe(`bytes ${start}-${end}/1000`);
      expect(await res.text(), range).toBe(body.slice(start, end + 1));
    }
  });

  it("slices every body type to the requested bytes", async () => {
    const bodies: [string, () => BodyInit][] = [
      ["string", () => "0123456789"],
      ["Uint8Array", () => new TextEncoder().encode("0123456789")],
      ["ArrayBuffer", () => new TextEncoder().encode("0123456789").buffer],
      ["Blob", () => new Blob(["0123456789"])],
      ["ReadableStream", () => new Response("0123456789").body!],
    ];
    for (const [i, [name, getBody]] of bodies.entries()) {
      t.app.all(`/types${i}/**`, (event) =>
        serveStatic(event, { getContents: getBody, getMeta: () => ({ size: 10 }) }),
      );
      const res = await t.fetch(`/types${i}/digits.txt`, { headers: { range: "bytes=2-4" } });
      expect(res.status, name).toBe(206);
      expect(await res.text(), name).toBe("234");
    }
  });

  it("streams a long body and stops after the requested bytes", async () => {
    t.app.all("/stream/**", (event) =>
      serveStatic(event, {
        getContents: () =>
          new ReadableStream<Uint8Array>({
            start(controller) {
              for (let i = 0; i < body.length; i += 100) {
                controller.enqueue(new TextEncoder().encode(body.slice(i, i + 100)));
              }
              controller.close();
            },
          }),
        getMeta: () => ({ size: 1000 }),
      }),
    );
    const tail = await t.fetch("/stream/a.txt", { headers: { range: "bytes=998-999" } });
    expect(tail.status).toBe(206);
    expect(await tail.text()).toBe("89");

    const middle = await t.fetch("/stream/a.txt", { headers: { range: "bytes=150-249" } });
    expect(await middle.text()).toBe(body.slice(150, 250));
  });

  it("answers HEAD with headers only and without reading the body", async () => {
    const res = await t.fetch("/range/a.txt", {
      method: "HEAD",
      headers: { range: "bytes=0-99" },
    });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-99/1000");
    expect(res.headers.get("content-length")).toBe("100");
    expect(await res.text()).toBe("");
    expect(getContents).not.toHaveBeenCalled();
  });

  it("answers unsatisfiable ranges with 416", async () => {
    for (const range of ["bytes=5000-6000", "bytes=-0", "bytes=1000-"]) {
      const res = await t.fetch("/range/a.txt", { headers: { range } });
      expect(res.status, range).toBe(416);
      expect(res.headers.get("content-range"), range).toBe("bytes */1000");
      expect(res.headers.get("content-length"), range).toBe("0");
      expect(await res.text(), range).toBe("");
    }
  });

  it("answers any range on an empty asset with 416", async () => {
    t.app.all("/empty/**", (event) =>
      serveStatic(event, { getContents: () => "", getMeta: () => ({ size: 0 }) }),
    );
    const res = await t.fetch("/empty/a.txt", { headers: { range: "bytes=0-0" } });
    expect(res.status).toBe(416);
    expect(res.headers.get("content-range")).toBe("bytes */0");
  });

  it("ignores malformed, multi-range and non-bytes Range headers", async () => {
    for (const range of [
      "bytes=0-10,20-30",
      "bytes=0-10, ",
      "bytes=abc",
      "items=0-1",
      "bytes=5-3",
      "bytes=-",
    ]) {
      const res = await t.fetch("/range/a.txt", { headers: { range } });
      expect(res.status, range).toBe(200);
      expect(res.headers.get("content-length"), range).toBe("1000");
      expect(res.headers.get("content-range"), range).toBeNull();
      expect(await res.text(), range).toBe(body);
    }
  });

  it("ignores Range when the size is unknown", async () => {
    t.app.all("/nosize/**", (event) =>
      serveStatic(event, { getContents: () => body, getMeta: () => ({ type: "text/plain" }) }),
    );
    const res = await t.fetch("/nosize/a.txt", { headers: { range: "bytes=0-99" } });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
    expect(await res.text()).toBe(body);
  });

  it("applies Range only when If-Range matches the current validator", async () => {
    const mtime = 1_700_000_000_000;
    t.app.all("/validators/**", (event) =>
      serveStatic(event, {
        getContents: () => body,
        getMeta: () => ({ etag: '"abc"', mtime, size: 1000 }),
      }),
    );
    for (const [ifRange, status] of [
      ['"xyz"', 200],
      ['"abc"', 206],
      ['W/"abc"', 200],
      [new Date(mtime).toUTCString(), 206],
      [new Date(mtime + 1000).toUTCString(), 200],
    ] as const) {
      const res = await t.fetch("/validators/a.txt", {
        headers: { range: "bytes=0-99", "if-range": ifRange },
      });
      expect(res.status, ifRange).toBe(status);
    }

    const withoutRange = await t.fetch("/validators/a.txt", { headers: { "if-range": '"xyz"' } });
    expect(withoutRange.status).toBe(200);
  });

  it("keeps 304 ahead of Range", async () => {
    const res = await t.fetch("/range/a.txt", {
      headers: { "if-none-match": '"abc"', range: "bytes=0-99" },
    });
    expect(res.status).toBe(304);
    expect(res.headers.get("accept-ranges")).toBe("bytes");
  });

  it("applies Range to the selected encoded variant", async () => {
    // A non-standard coding: undici would try to decode a partial gzip body.
    t.app.all("/enc/**", (event) =>
      serveStatic(event, {
        getContents: (id) => (id.endsWith(".raw") ? "r".repeat(400) : body),
        getMeta: (id) => (id.endsWith(".raw") ? { encoding: "x-raw", size: 400 } : { size: 1000 }),
        encodings: { "x-raw": ".raw" },
      }),
    );
    const res = await t.fetch("/enc/app.js", {
      headers: { "accept-encoding": "x-raw", range: "bytes=0-99" },
    });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-encoding")).toBe("x-raw");
    expect(res.headers.get("content-range")).toBe("bytes 0-99/400");
