/**
 * Emit only the bytes of `range` from a stream, then terminate it. `getContents` has no
 * offset, so the source is read from its beginning (R-01).
 */
function sliceStream(
  stream: ReadableStream<Uint8Array>,
  range: ByteRange,
): ReadableStream<Uint8Array> {
  let position = 0;
  return stream.pipeThrough(
    new TransformStream<Uint8Array, Uint8Array>({
      transform(chunk, controller) {
        const chunkStart = position;
        const chunkEnd = position + chunk.byteLength;
        position = chunkEnd;
        if (chunkEnd <= range.start) {
          return;
        }
        const from = Math.max(range.start - chunkStart, 0);
        const to = Math.min(range.end + 1 - chunkStart, chunk.byteLength);
        controller.enqueue(chunk.subarray(from, to));
        if (chunkEnd > range.end) {
          controller.terminate();
        }
      },
    }),
  );
}

